import json,pathlib
H=pathlib.Path(__file__).resolve().parent
DATE='2026-10-25'
records=[]
def add(code,identifier,title,year,pmid,population,intervention,comparator,endpoint,findings,limitations,context,doi=None):
    records.append({'code':code,'protocol_id':'nccp-'+code+('-v5' if code=='00254' else '-vcurrent'),'evidence_id':'v08420_'+identifier,'source_id':identifier,'trial_acronym':title,'publication_title':title,'publication_url':'https://pubmed.ncbi.nlm.nih.gov/'+pmid+'/','doi':doi,'year':year,'study_design':population,'trial_population':population,'intervention':intervention,'comparator':comparator,'evidence_context':context,'primary_endpoint':endpoint,'relevance_summary':' '.join(findings),'key_findings':findings,'limitations':limitations,'source_checked_date':DATE,'review_status':'Source reconciled; independent clinical and oncology pharmacy review pending','audience':'clinician_only'})
add('00254','ATAC10','ATAC: ten-year analysis of initial adjuvant anastrozole versus tamoxifen',2010,'21087898','Postmenopausal early breast cancer; 6,241 women in the two monotherapy groups, including 5,216 with hormone-receptor-positive disease; median follow-up 120 months.','Anastrozole 1 mg daily for 5 years','Tamoxifen 20 mg daily for 5 years','Disease-free survival; recurrence endpoints and overall mortality also reported.',['In the HR-positive subgroup, DFS HR 0.86 (95% CI 0.78–0.95) and time-to-recurrence HR 0.79 (0.70–0.89) favoured anastrozole.','Absolute recurrence difference at 10 years was 4.3 percentage points. Overall mortality was not significantly different: HR 0.95 (0.84–1.06).'],'Adjuvant results cannot supply an advanced-disease prognosis or authorise AI monotherapy with functioning ovaries. Fractures were more frequent during active anastrozole treatment. The trial is not evidence for restarting a complete five-year course after a tamoxifen switch.','Initial adjuvant treatment; not a metastatic or neoadjuvant benefit estimate.','10.1016/S1470-2045(10)70257-6')
add('00371','BIG1_98_LTFU','BIG 1-98: long-term follow-up of letrozole versus tamoxifen',2019,'30475668','Postmenopausal HR-positive early breast cancer; 8,010 randomized overall, including a 4,922-patient monotherapy comparison. Long-term follow-up was available from participating centres for 3,833 of 4,433 eligible patients; median follow-up 12.6 years.','Letrozole 2.5 mg daily for 5 years','Tamoxifen 20 mg daily for 5 years','Disease-free survival; other efficacy and safety endpoints also followed.',['At median 12.6 years, the DFS estimate for letrozole versus tamoxifen was HR 0.91 (95% CI 0.81–1.01); this confidence interval includes no difference.','The latest report therefore must not be described as a statistically significant long-term DFS advantage on the strength of the earlier 8.7-year estimate.'],'The randomized trial was extended observationally after sponsor follow-up; weighted analyses addressed participating-centre coverage. Attrition and selective crossover complicate interpretation. Earlier significant estimates and this later estimate are different timepoints/analyses, not interchangeable numbers. This adjuvant trial does not quantify benefit in neoadjuvant or advanced disease.','Initial adjuvant treatment; latest long-term primary report identified in this audit.','10.1200/JCO.18.00440')
add('00371','MA17','MA.17: extended adjuvant letrozole following tamoxifen',2005,'16145047','5,187 postmenopausal women after approximately 5 years of tamoxifen; double-blind randomized placebo-controlled trial, median follow-up 30 months at this updated report.','Letrozole 2.5 mg daily, planned for 5 years','Placebo','Disease-free survival; distant disease-free survival and overall survival secondary.',['DFS HR 0.58 (95% CI 0.45–0.76; P<0.001) and distant DFS HR 0.60 (0.43–0.84; P=0.002) favoured letrozole.','Overall survival was not significantly improved across the whole randomized population: HR 0.82 (0.57–1.19; P=0.30).'],'Stopped early for benefit, which affects follow-up and later crossover interpretation. The node-positive OS subgroup finding must not be presented as a whole-trial survival benefit. Supports a defined post-tamoxifen extension, not indefinite therapy or automatic extension after every preceding AI course.','Extended adjuvant treatment after tamoxifen.','10.1093/jnci/dji250')
add('00371','P024','P024: preoperative letrozole versus tamoxifen',2001,'11822750','337 postmenopausal women with untreated ER- and/or PgR-positive primary breast cancer initially unsuitable for breast-conserving surgery; randomized double-blind comparison.','Letrozole 2.5 mg daily for 4 months','Tamoxifen 20 mg daily for 4 months','Objective clinical response assessed by palpation.',['Clinical response was 55% versus 36% (P<0.001), favouring letrozole.','Breast-conserving surgery occurred in 45% versus 35% (P=0.022).'],'Response and surgical conversion are not overall-survival outcomes. The historical study population is not identical to current labelled neoadjuvant selection. Its four-month duration must not replace NCCP’s response-guided 4–8-month pathway or justify delaying indicated surgery.','Neoadjuvant treatment, distinct from adjuvant recurrence prevention and advanced-disease control.')
add('00376','IES10','IES: long-term follow-up after switching from tamoxifen to exemestane',2017,'28467729','4,724 postmenopausal women who remained disease-free after 2–3 years of adjuvant tamoxifen; ER-positive/unknown analysis comprised 4,599; median follow-up 120 months.','Switch to exemestane 25 mg daily to complete 5 total years of endocrine therapy','Continue tamoxifen to complete 5 total years','Breast-cancer-free survival (BCFS), censoring intercurrent deaths, was the principal long-term survival endpoint of interest.',['In ER-positive/unknown disease, 10-year BCFS absolute difference was 4.0 percentage points (95% CI 1.2–6.7); HR 0.81 (0.72–0.92), favouring the switch.','Overall survival in that analysis was not statistically significant: HR 0.89 (0.78–1.01; P=0.08), absolute difference 2.1 percentage points (−0.5 to 4.6).'],'BCFS is not interchangeable with DFS or overall survival. This strategy totals five endocrine-treatment years; it does not add five exemestane years to the preceding tamoxifen course. It cannot establish benefit for every broader NCCP extended-adjuvant indication, premenopausal monotherapy or advanced-disease prognosis.','Defined adjuvant tamoxifen-to-exemestane switch.','10.1200/JCO.2016.70.5640')
add('00376','EXE_MEGESTROL','Exemestane versus megestrol after tamoxifen failure in advanced breast cancer',2000,'10735887','769 postmenopausal women with advanced breast cancer progressing after tamoxifen; randomized double-blind trial: exemestane 366, megestrol 403.','Exemestane 25 mg daily','Megestrol acetate 40 mg four times daily (160 mg total daily)','Objective response and time-to-event efficacy outcomes in advanced disease.',['Median time to progression was 20.3 versus 16.6 weeks (P=0.037), favouring exemestane.','Overall response was 15.0% versus 12.4%; this difference should not be labelled statistically significant.'],'Historical post-tamoxifen population and comparator predate modern CDK4/6, PI3K/AKT and oral SERD treatment sequences. Do not use these short historical medians as an individual prognosis or as expected benefit following current targeted combinations. Keep this advanced evidence separate from IES adjuvant BCFS.','Advanced disease after tamoxifen failure, not an adjuvant trial.')
facts=json.loads((H/'service-facts.json').read_text())
out={'release':'0.84.20','checked_date':DATE,'audience':'clinician_only','patient_display_policy':'Numerical trial outcomes and study-population counts are excluded from patient content. Use service-facts.patient_updates.evidence instead.','mechanisms':{c:facts['regimens'][c]['mechanism'] for c in facts['regimens']},'evidence_records':records,'coverage_limitations':['Selected regimen-relevant primary reports, including later follow-up, were reviewed; this is not a systematic treatment-sequencing review.','Anastrozole and letrozole advanced disease do not receive a manufactured benefit estimate from adjuvant data.','No study establishes ovarian suppression from an AI tablet alone or interchangeable dose/monitoring rules across the three drugs.']}
(H/'evidence.json').write_text(json.dumps(out,indent=2,ensure_ascii=False)+'\n')

s=json.loads((H/'sources.json').read_text())
s['sources']=[x for x in s['sources'] if x.get('authority')!='Primary trial publication']
for r in records:s['sources'].append({'id':r['source_id'],'title':r['publication_title'],'url':r['publication_url'],'doi':r['doi'],'checked_date':DATE,'authority':'Primary trial publication','audience':'clinician_only'})
(H/'sources.json').write_text(json.dumps(s,indent=2,ensure_ascii=False)+'\n')
